<original_code>
#include <bits/stdc++.h>

using namespace std;

#define F first
#define S second
#define MP make_pair
#define all(x) (x).begin(), (x).end()

typedef long long ll;
typedef unsigned long long ull;
typedef long double ld;

const double EPS = 1e-9;
const double PI = acos(-1.0);
const int MOD = 1000 * 1000 * 1000 + 7;
const int INF = 2000 * 1000 * 1000;
const int MAXN = 210;
const int MAXM = 2 * MAXN * MAXN;
const int dx[] = {1, 0, 0, -1};
const int dy[] = {0, 1, -1, 0};
const int S = MAXN - 2;
const int T = MAXN - 1;

template <typename T>
inline T square(T n) {
    return n * n;
}

struct MaxFlow {
    int to[MAXM];
    int flow[MAXM], cap[MAXM];
    int lastEdge;

    vector <int> g[MAXN];

    bool used[MAXN];

    MaxFlow() : lastEdge(0) { }

    void addEdge(int from, int to, int capacity) {
        this->to[lastEdge] = to;
        this->flow[lastEdge] = 0;
        this->cap[lastEdge] = capacity;
        g[from].push_back(lastEdge++);

        this->to[lastEdge] = from;
        this->flow[lastEdge] = 0;
        this->cap[lastEdge] = 0;
        g[to].push_back(lastEdge++);
    }

    bool dfs(int v, int sink, int flowAmount) {
        if (v == sink) {
            return true;
        }

        used[v] = true;

        for (int idx: g[v]) {
            if (!used[to[idx]] && cap[idx] - flow[idx] >= flowAmount &&
                dfs(to[idx], sink, flowAmount)) {

                flow[idx] += flowAmount;
                flow[idx ^ 1] -= flowAmount;

                return true;
            }
        }

        return false;
    }

    int getMaxFlow(int source, int sink) {
        int flowAmount = 1 << 30;
        int totalFlow = 0;

        while (flowAmount > 0) {
            if (dfs(source, sink, flowAmount)) {
                totalFlow += flowAmount;
            } else {
                flowAmount >>= 1;
            }

            memset(used, false, sizeof used);
        }

        return totalFlow;
    }
};

MaxFlow maxFlow;

int n, t;
char grid1[15][15];
char grid2[15][15];
int distance[15][15];
bool visited[15][15];

bool isValid(int x, int y) {
    return 0 <= x && x < n &&
           0 <= y && y < n &&
           grid1[x][y] != 'Y' &&
           grid1[x][y] != 'Z';
}

void bfsDeath(int x, int y) {
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            distance[i][j] = INF;
        }
    }

    queue <int> X, Y;
    distance[x][y] = 0;
    X.push(x);
    Y.push(y);

    while (!X.empty()) {
        assert(!Y.empty());

        int curx = X.front();
        int cury = Y.front();

        X.pop();
        Y.pop();

        for (int k = 0; k < 4; k++) {
            int tx = curx + dx[k];
            int ty = cury + dy[k];

            if (isValid(tx, ty) && distance[tx][ty] == INF) {
                distance[tx][ty] = distance[curx][cury] + 1;
                X.push(tx);
                Y.push(ty);
            }
        }
    }
}

void runBFS(int x, int y) {
    queue <int> X, Y, lev;
    memset(visited, false, sizeof visited);

    visited[x][y] = true;
    X.push(x);
    Y.push(y);
    lev.push(0);

    while (!X.empty()) {
        assert(!Y.empty());

        int curx = X.front();
        int cury = Y.front();
        int curlev = lev.front();

        X.pop();
        Y.pop();
        lev.pop();

        if (isdigit(grid2[curx][cury]) && grid2[curx][cury] != '0') {
            maxFlow.addEdge(x * n + y, square(n) + 1 + curx * n + cury, INF);
        }

        if (curlev >= t) {
            continue;
        }

        for (int k = 0; k < 4; k++) {
            int tx = curx + dx[k];
            int ty = cury + dy[k];

            if (isValid(tx, ty) && !visited[tx][ty]) {
                if (distance[tx][ty] > curlev + 1) {
                    X.push(tx);
                    Y.push(ty);

                    lev.push(curlev + 1);
                } else if (distance[tx][ty] > curlev && isdigit(grid2[tx][ty]) && grid2[tx][ty] != '0') {
                    maxFlow.addEdge(x * n + y, square(n) + 1 + tx * n + ty, INF);
                }

                visited[tx][ty] = true;
            }
        }
    }
}

void build() {

    int posi = -1, posj = -1;
    for (int i = 0; i < n && posi == -1; i++) {
        for (int j = 0; j < n && posi == -1; j++) {
            if (grid1[i][j] == 'Z') {
                posi = i, posj = j;
            }
        }
    }

    bfsDeath(posi, posj);

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (isdigit(grid1[i][j]) && grid1[i][j] != '0') {
                maxFlow.addEdge(S, i * n + j, grid1[i][j] - '0');
            }
        }
    }

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (isdigit(grid2[i][j]) && grid2[i][j] != '0') {
                maxFlow.addEdge(i * n + j + square(n) + 1, T, grid2[i][j] - '0');
            }
        }
    }

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (isdigit(grid1[i][j]) && grid1[i][j] != '0') {
                runBFS(i, j);
            }
        }
    }
}

int main() {
#ifndef ONLINE_JUDGE
    freopen("in", "r", stdin);
#endif

    scanf("%d %d", &n, &t);

    scanf("\n");
    for (int i = 0; i < n; i++) {
        gets(grid1[i]);
    }

    scanf("\n");
    for (int i = 0; i < n; i++) {
        gets(grid2[i]);
    }

    build();

    printf("%d\n", maxFlow.getMaxFlow(S, T));

    return 0;
}
